CREATE TABLE liquidaciones.liquidation_prefixes(crop text PRIMARY KEY,prefix text NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true,description text,created_at timestamptz,updated_at timestamptz);
CREATE TABLE liquidaciones.liquidation_sequences(crop text NOT NULL,campaign text NOT NULL,company text NOT NULL,prefix text NOT NULL,last_sequence bigint NOT NULL,initialized_from text NOT NULL,legacy_last_idliq text,initialized_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,PRIMARY KEY(crop,campaign,company));
CREATE TABLE liquidaciones.split_rules(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,source_member_id bigint NOT NULL,source_member_name text,split_type text NOT NULL,campaign text,crop text,variety text,remittance_id bigint,effective_from date,effective_to date,active boolean NOT NULL DEFAULT true,priority integer NOT NULL DEFAULT 100,notes text,source text,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE liquidaciones.split_rule_recipients(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,rule_id bigint NOT NULL REFERENCES liquidaciones.split_rules(id) ON DELETE CASCADE,recipient_member_id bigint NOT NULL,recipient_member_name text,value numeric(18,10) NOT NULL,is_residual boolean NOT NULL DEFAULT false,sort_order integer NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true);
CREATE TABLE liquidaciones.liquidation_batches(batch_id uuid PRIMARY KEY,remesa_id bigint NOT NULL,remesa_name text NOT NULL,campaign text NOT NULL,company text NOT NULL,crop text NOT NULL,payment_date date,calculation_fingerprint varchar(64) NOT NULL,original_line_count integer NOT NULL,final_line_count integer NOT NULL,status varchar(16) NOT NULL CHECK(status IN('ACTIVE','PARTIAL','SUPERSEDED','VOIDED','FAILED')),created_at timestamptz NOT NULL,created_by text,voided_at timestamptz,voided_by text,void_reason text,operation_type varchar(16) NOT NULL DEFAULT 'ORIGINAL' CHECK(operation_type IN('ORIGINAL','REVERSAL','REPLACEMENT')),original_batch_id uuid REFERENCES liquidaciones.liquidation_batches(batch_id),replacement_batch_id uuid REFERENCES liquidaciones.liquidation_batches(batch_id),modification_group_id uuid,supersedes_batch_id uuid REFERENCES liquidaciones.liquidation_batches(batch_id),modification_reason text);
CREATE TABLE liquidaciones.liquidaciones(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_liq text NOT NULL UNIQUE,fecha date NOT NULL,cultivo text NOT NULL,campana text NOT NULL,empresa text NOT NULL,id_socio bigint NOT NULL,socio text NOT NULL,cod_art text,variedad text NOT NULL,neto numeric(18,4) NOT NULL,imp_bruto numeric(18,6) NOT NULL,precio_comer numeric(18,10),recoleccion numeric(18,6) NOT NULL,cuota_ha numeric(18,6) NOT NULL,bp_calidad numeric(18,6) NOT NULL,b_transporte numeric(18,6) NOT NULL,b_global numeric(18,6) NOT NULL,base_i numeric(18,6) NOT NULL,precio_medio numeric(18,10),iva numeric(18,6) NOT NULL,retencion numeric(18,6) NOT NULL,importe_total numeric(18,6) NOT NULL,id_concepto_liq bigint NOT NULL,concepto_liq text NOT NULL,tipo text NOT NULL,remesa_id bigint,source_member_id bigint NOT NULL,recipient_member_id bigint NOT NULL,source_member_name text,source_variety text,source_liquidation_key text NOT NULL,split_rule_id bigint REFERENCES liquidaciones.split_rules(id),split_type text,split_factor numeric(18,10) NOT NULL DEFAULT 1,is_split boolean NOT NULL DEFAULT false,batch_id uuid REFERENCES liquidaciones.liquidation_batches(batch_id),status varchar(16) NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL,created_by text,calculation_fingerprint varchar(64),voided_at timestamptz,voided_by text,void_reason text,operation_type varchar(16) NOT NULL DEFAULT 'ORIGINAL',original_batch_id uuid,original_id_liq text,replacement_batch_id uuid,replacement_id_liq text,modification_group_id uuid,variety_code text,variety_name text,variety_group_code text,variety_group_name text);
CREATE TABLE liquidaciones.legacy_imports(name text PRIMARY KEY,imported_at timestamptz NOT NULL,details jsonb);
